window.DOSIK=window.DOSIK||{};DOSIK["yc_group3"]={"1":[{"t":"tree","title":"집단상담","root":"집단상담의 개념과 목적","branches":[["개념","여러 사람들이 모여서 자신의 성장과 변화를 도모하는 상담경험이다"],["대인관계 기술","다양한 집단원들과 함께 대인관계 기술을 연습할 수 있다"],["목표","집단 전체의 목표와 집단원 개인의 목표로 나눌 수 있다"],["압력","집단 참여에 대한 압력을 받아 심리적 부담을 느낄 수 있다"]]}],"2":[{"t":"tree","title":"집단역동","root":"집단의 발달단계","branches":[["중첩","집단의 발달단계는 실제로 중첩되기도 한다"],["갈등","집단 과업이 달성된 후에도 새로운 갈등이 일어날 수 있다"],["정체와 퇴보","다음 단계에 진입해서 정체되기도 하고, 일시적으로 이전 단계로 퇴보하는 경우도 있다"],["변화","집단은 역동적, 지속적으로 변화하는 특징을 지니고 있다"]]}],"3":[{"t":"tree","title":"집단응집력","root":"집단상담의 치료적 요인(얄롬)","branches":[["치료적 힘","집단응집력은 그 자체가 강력한 치료적인 힘이다"],["뜻풀이","집단원의 내면세계를 정서적으로 공유하고 집단으로부터 수용되는 것이다"],["개인상담","개인상담의 치료적 관계와 유사한 개념이다"],["효과","집단응집력이 높을수록 출석, 참여, 상호지지의 비율이 더 높아진다"]]}],"4":[{"t":"table","title":"집단상담 유형","head":["유형","내용"],"rows":[["집중적 집단상담","일정기간 동안 집중적으로 실시하는 형태이며, 마라톤 집단이 해당된다 · 마라톤집단에서는 며칠 동안 집중 회기를 통해 심화된 상호작용이 활성화될 수 있다"],["자조집단","공통의 관심사나 어려움을 경험했던 사람들끼리 집단을 이끌어간다"],["과업집단","집단원들에게 당면한 과제를 해결할 필요가 있을 때 운영되는 집단이다 · 특정과업을 완수하기 위한 목적으로 구성된다"],["성장집단","참만남 집단, 자기성장 집단, 감수성 훈련집단이 해당된다 · 자신의 잠재력 개발에 관심 있는 사람들로 구성된다"],["교육집단","상담자는 집단원의 학습효과를 극대화하기 위해 · 교육자와 촉진자의 역할을 동시에 수행한다"],["지지집단","공통적인 관심사가 있는 집단원들로 구성되어 특정문제와 관심사에 대해 공유한다"]]},{"t":"vs","title":"개방집단과 폐쇄집단","cols":[{"name":"개방집단","items":["집단원의 변동이 가능하므로 · 폐쇄집단보다 다양한 사람들과 상호작용할 수 있다"]},{"name":"폐쇄집단","items":["일부 집단원이 중도에 탈락할 경우 · 집단 크기가 너무 작아질 염려가 있다"]}]},{"t":"def","term":"동질집단","text":"이질집단보다 빨리 자기개방이 이루어지고 유대감이 형성될 수 있다"}],"5":[{"t":"tree","title":"집단상담자의 자질과 역할","root":"집단상담자","branches":[["태도","집단상담자는 열정적이고 긍정적인 태도를 갖는다"],["비밀보장","현실적으로 완벽한 비밀보장이 어렵다는 것을 사전에 알려 준다"],["개인상담 권유","집단상담이 적절하지 않다고 판단되는 경우 개인상담을 권유한다"],["집단을 떠나고 싶어하는 경우","폐쇄집단에서 집단원이 집단을 떠나고 싶어하면 이를 존중해 준다"],["공동지도자","집단회기 전후에 공동지도자와 집단에 대한 계획과 소감, 서로의 협력에 대해 논의한다"]]},{"t":"vs","title":"공동지도자","cols":[{"name":"이점","items":["지도자의 신체적ㆍ정서적 소진 가능성이 줄어든다","지도자 중 한 명이 역전이가 일어날 때 도움이 된다","지도자 중 한 명은 강한 정서를 표현하는 집단원에 집중하고, 다른 지도자는 나머지 집단원들의 반응에 주목할 수 있다"]},{"name":"단점","items":["지도자가 다른 지도자에 대항하여 집단원과 한 편을 이루는 단점도 있다"]}]}],"6":[{"t":"tree","title":"사전동의","root":"윤리와 사전동의","branches":[["목표와 한계","집단상담의 목표와 한계에 대해 명확히 알려야 한다"],["권리와 책임","집단상담자와 집단원 모두의 권리와 책임에 대해 알려야 한다"],["만 14세 미만","청소년인 경우, 보호자 또는 법정대리인의 · 상담 활동에 대한 사전 동의를 구해야 한다"],["선택","집단상담에 대해 집단원이 충분한 설명을 듣고 · 선택할 수 있도록 적절한 정보를 제공해야 한다"]]}],"7":[{"t":"tree","title":"집단의 계획","root":"집단상담의 계획","branches":[["주제와 목적","대상에게 맞는 집단의 주제와 목적을 설정하고, 이를 달성하기 위한 목표를 구체화한다"],["크기","집단원의 성숙도, 집단의 유형 등에 따라 집단의 크기를 정한다"],["장소","집단 진행에 방해가 되지 않는 조용한 공간으로 선택한다"],["시간과 주기","집단의 종류나 목적에 따라 모임의 시간과 주기를 결정한다"]]},{"t":"tree","title":"참여 전 활동","root":"집단상담의 계획과 구조화","branches":[["이해","집단상담에 관한 이해를 높인다"],["정보","집단참여 촉진을 위한 정보를 제공한다"],["선별","집단에 참여하기 어려운 집단원을 선별할 수 있다"],["기대","집단상담에 대한 현실적인 기대 형성을 돕는다"]]},{"t":"tree","title":"구조화","root":"구조화","branches":[["이론적 배경","이론적 배경에 따라 구조화의 정도와 종류가 다르다"],["초기 단계","구조화는 집단원의 집단참여에 대한 불안을 어느 정도 줄여준다"],["갈등 발생","구조화 집단에서 갈등이 발생할 경우 구조화 활동을 잠시 미루고 갈등을 다루는 것이 바람직 하다"],["지나친 구조화","집단의 발달을 방해한다"]]}],"8":[{"t":"tree","title":"초기단계 개입","root":"초기단계","branches":[["염려와 질문","집단원들의 염려와 질문을 개방적으로 다룬다"],["구조화","집단에 대한 구조화를 실시하여 집단에 대해 안내한다"],["모범","적극적 경청과 공감적 반응으로 집단행동의 모범을 보인다"],["상호작용","집단상담자에게 집중되는 것을 피하고 집단원간의 상호작용을 촉진시킨다"],["책임과 역할","집단상담자와 집단원의 책임과 역할을 명확히 한다"],["대인관계 기술","적극적으로 경청하고 반응하기와 같은 기본적인 대인관계 기술을 알려준다"]]},{"t":"tree","title":"초기단계 집단원 지원","root":"초기단계","branches":[["개인 목표","집단원들이 구체적인 개인 목표를 설정하도록 돕는다"],["기대","집단원의 집단에 대한 기대를 탐색한다"],["불안","집단원의 집단참여에 대한 불안감 해소를 돕는다"],["참여 독려","집단에서 이루어지는 작업은 쉽지 않음을 알리고 적극적인 참여를 독려한다"],["기본규칙","집단원과 함께 집단의 기본규칙에 관하여 논의한다"]]}],"13":[{"t":"table","title":"집단원 유형별 개입","head":["집단원","개입"],"rows":[["침묵하는 집단원","집단참여를 격려한다"],["장황하게 설명하는 집단원","요약해서 말해줄 것을 요청한다"],["비자발적인 집단원","집단참여에 대한 감정을 표현할 수 있도록 돕는다"],["대화를 독점하는 집단원","그러한 행동을 통해 얻고자 하는 바를 탐색한다"]]},{"t":"vs","title":"피드백","cols":[{"name":"긍정적 피드백","items":["부정적인 피드백보다 더 잘 받아들여진다"]},{"name":"부정적 피드백","items":["긍정적인 피드백 이후에 줄 때 더 쉽게 받아들여진다","집단 발달이 어느 정도 이루어지고 · 신뢰관계가 형성되었을 때 하는 것이 효과적이다"]},{"name":"지금-여기 피드백","items":["집단에서의 행동과 관련된 ‘지금-여기’ 피드백이 · 모호한 피드백보다 더 도움이 된다"]}]},{"t":"tree","title":"집단 특유의 기법","root":"집단 특유의 상담기법","branches":[["솔직한 대화","집단원과 집단의 진행과정에 대해 솔직하게 이야기를 나눈다"],["인격","문제행동을 보이는 집단원의 인격을 폄하하지 않는다"],["갈등","갈등을 회피하지 않고 탐색할 수 있는 방법을 찾는다"],["방어","방어하는 행동을 멈추도록 강요하지 않는다"]]}],"14":[{"t":"tree","title":"집단 과정의 현상","root":"정신분석 및 아들러 개인심리학적 접근","branches":[["전이","전이 반응을 탐색할 수 있는 기회를 제공한다"],["역전이","집단원에 대한 역전이가 일어날 수 있다"],["통찰","집단원의 통찰을 나누는 것은 집단의 발전을 촉진한다"],["저항","방관하거나 불필요한 이야기를 길게 하는 식의 저항이 나타난다"],["투사","수용할 수 없는 자신의 생각, 감정, 행동, 동기를 타인에게 돌리는 것이다"]]},{"t":"tree","title":"집단원 파악과 개입","root":"집단원 파악과 개입","branches":[["생활양식","집단원의 생활양식을 파악하기 위해 가족구도를 탐색한다"],["사회적 상황","집단원의 사회적 상황과 사회적 태도를 파악한다"],["새로운 행동","새로운 행동을 시도하고 현실을 검증할 기회를 제공한다"],["자기 파괴적 행동","자기 파괴적인 행동을 반복할 때 잠시 멈추고 자신을 살펴보도록 한다"]]},{"t":"flow","title":"아들러 상담 단계","steps":["상담관계형성 단계에서는 상담자와 집단원은 우호적이며 대등한 관계가 형성되어야 한다","분석ㆍ사정 단계에서는 집단원의 부적절한 생활양식을 파악하고 집단원의 신념, 감정, 동기, 목표를 이해한다","해석ㆍ통찰 단계에서는 상담자는 집단원의 진술에 대한 해석을 통해 집단원의 자각과 통찰을 돕는다"]}],"15":[{"t":"tree","title":"인간중심 접근","root":"인간중심 접근","branches":[["진실성","집단상담자는 진실해야 하지만 무분별하게 개방적이어서는 안 된다"],["성장 촉진","집단상담자의 진실성, 수용, 공감은 집단원의 성장을 촉진한다"],["문화","다양한 문화적 배경을 가진 집단원들 간의 상호 이해에 적합하다"],["태도","구체적인 기법보다는 집단상담자의 촉진적인 태도를 강조한다"]]},{"t":"def","term":"투사","text":"자신의 요구 또는 감정을 자각하는 것이 두려워 책임을 타인에게 돌리는 현상이다"},{"t":"table","title":"접근별 집단상담","head":["접근","내용"],"rows":[["게슈탈트","집단원이 자신과 환경을 이해하고 자신을 수용하며 접촉할 수 있는 힘을 증진시킨다"],["정신분석","과거의 경험을 분석ㆍ해석하고 무의식적 수준에서 작동하는 심리적 역동에 대해 통찰하도록 한다"],["개인심리학","격려를 통해 집단원들에게 용기를 북돋아 주고 사회적 관심을 갖게 하고, 생활양식을 수정하도록 한다"],["현실치료","스스로 책임지고 선택한 방법으로 각자의 심리적 욕구를 충족할 수 있도록 한다"],["합리적 정서행동치료","비합리적 신념을 변화시킴으로써 부정적인 감정을 완화시킨다"]]}],"16":[{"t":"flow","title":"심리극 단계","steps":["워밍업 단계에서는 심리극이 시작되기 전 집단의 목표, 한계 등을 안내한다 · 연출자의 준비, 신뢰감 형성 등의 활동이 포함된다","시연단계에서는 연출자가 다양한 기법을 활용하여 주인공의 무의식 속 욕망, 갈등 등이 드러나게 한다","종결단계에서는 연출자는 참여자들이 심리극 과정에 참여하면서 느낀 소감을 주인공과 함께 나누도록 돕는다"]},{"t":"tree","title":"실존주의 집단","root":"실존주의","branches":[["목표","집단의 목표는 자신이 자기 삶의 주인이어야 한다는 자유를 인식하고 수용하는 것이다"],["집단상황","집단상황을 집단원이 실제로 살고 기능하는 세계의 축소판으로 본다"],["실존적 문제","집단원들이 실존적 문제를 나눔으로써 자신을 발견하도록 돕는다"],["자유와 책임","집단원들은 기본적으로 자유로운 존재이기에 자유에 동반되는 책임을 받아들여야 한다"]]}],"17":[{"t":"tree","title":"합리적 정서행동치료 집단(행동주의ㆍ인지행동 및 교류분석적 접근)","root":"인지행동(REBT)","branches":[["목표","집단원의 비합리적 신념을 합리적 신념으로 바꾸는 것을 목표로 한다"],["기법","집단원의 인지적 변화를 위해 다양한 인지적, 정서적 기법을 활용한다"],["과제","집단원의 개인적인 변화를 촉진하기 위해 · 집단원과의 협의 하에 수행할 과제를 주고 확인한다"],["정서적 기법","합리적-정서적 상상하기, 유머 사용하기 등의 정서적 기법을 활용한다"]]},{"t":"def","term":"친숙한 정서","text":"어린 시절에 격려 받고 학습되어진 친숙한 정서로써 다양한 상황에서 경험된다"}],"18":[{"t":"vs","title":"현실치료와 해결중심ㆍ이야기치료","cols":[{"name":"현실치료","items":["집단원이 현재 무엇을 하고 있는지에 초점을 맞추도록 한다"]},{"name":"해결중심ㆍ이야기치료","items":["집단원이 자기 삶의 전문가이므로 · 상담자는 알지 못함의 자세를 취해야 한다","집단원이 자기 삶의 전문가라고 믿고 · ‘알지 못함’(not-knowing)의 자세를 취한다"]}]}],"19":[{"t":"tree","title":"청소년ㆍ학교 집단상담","root":"청소년ㆍ학교 집단상담의 실제","branches":[["주제","학습, 진로만이 아니라 문제행동 및 예방을 주제로 한다"],["승인","학교장의 승인을 받아 실시해야 한다"],["사전동의서","교육을 목적으로 실시하는 경우라도 반드시 사전동의서를 받아야 한다"],["놀이와 매체","집단원들의 관심을 높일 수 있도록 놀이나 매체를 활용할 수 있다"],["종결","집단 종결 전에 집단원에게 어느 정도의 기간을 두고 종결 시점을 상기시켜 준다"],["회기","매 회기를 철저히 준비하되 주어진 회기마다 구성과 주제를 조절할 수 있는 융통성이 있어야 한다"]]},{"t":"tree","title":"상담자의 준비와 안내","root":"청소년ㆍ학교 집단상담의 안내","branches":[["법률","아동ㆍ청소년과 관련된 법률을 숙지하고 있어야 한다"],["이점 설명","아동과 청소년이 집단에서 얻을 수 있는 이점을 학교 담당자, 교사, 부모에게 명확히 설명해야 한다"],["비밀유지","비밀유지의 한계에 대해 명확하게 알려준다"],["책임과 권리","집단원으로서의 책임과 권리를 인식할 수 있도록 한다"],["자기개방","감당할 수 있을 만큼의 자기개방을 하도록 안내한다"],["미완료","집단을 완료하지 못할 경우 어떤 결과가 초래되는지 안내한다"]]}],"20":[{"t":"table","title":"평가 대상과 주체","head":["구분","내용"],"rows":[["평가 대상","집단원, 집단상담자 및 집단상담 과정을 평가한다"],["집단원","집단원은 평가 대상이면서 평가자가 되기도 한다"],["상담기관","청소년 상담기관에서 집단상담을 실시할 경우 상담기관이 평가주체가 될 수 있다"],["심리검사","상담자가 집단상담 전후에 심리검사를 실시하여 집단원 행동 변화를 평가할 때 평가의 주체는 상담자, 평가 대상은 집단원이 된다"]]},{"t":"flow","title":"평가 시기","steps":["집단상담 계획단계에서부터 집단상담 평가에 대한 방향을 설정하여야 한다","집단상담 계획 시에 집단상담 효과성 평가를 위한 계획을 수립해야 한다","집단상담 실시 이전에 집단상담 수요 평가, 집단원 행동 기초선 평가를 실시할 수 있다","집단상담이 끝나고 1～2개월 후 추후평가를 실시하여 집단상담의 효과를 평가한다"]},{"t":"tree","title":"평가 방법","root":"집단상담의 평가","branches":[["면접","면접을 통한 평가는 특정 시점보다 전 과정에 걸쳐 이루어진다"],["평가방법","평가방법은 주로 면접, 심리검사, 관찰 등으로 이루어진다"],["소감과 경험보고서","집단원의 소감이나 경험보고서는 집단과정에 대한 중요한 평가 자료로 활용된다"],["양적 평가","심리검사를 통해 수치화된 정보를 수집하고 통계적으로 분석하는 것을 양적 평가라 한다"]]}]};
