(window.TNQ=window.TNQ||[]).push({"terms":{"집단응집력":{"d":"집단원들이 집단에 끌려 소속되려는 힘으로 집단 안에서 그 자체가 치료적 효과를 냅니다.","r":[]},"마라톤집단":{"d":"며칠 동안 오랜 시간 쉬지 않고 진행해 깊은 상호작용을 일으키는 집중적 집단상담입니다.","r":[]},"폐쇄집단":{"d":"처음 시작한 집단원만으로 끝까지 진행하며 중간에 새 성원을 받지 않는 집단입니다.","r":["이질집단"]},"이질집단":{"d":"나이나 문제, 성격이 서로 다른 사람들로 구성된 집단입니다.","r":["폐쇄집단"]},"공동지도자":{"d":"집단을 한 명이 아니라 두 명이 함께 이끌 때의 상담자들입니다.","r":["역전이"]},"역전이":{"d":"상담자가 내담자에게 자신의 과거 감정이나 욕구를 투영해 반응하는 현상입니다.","r":["전이","공동지도자"]},"전이":{"d":"내담자가 과거 중요한 인물에게 가졌던 감정을 상담자에게 옮겨 느끼는 현상입니다.","r":["역전이"]},"저항":{"d":"집단원이 무의식적으로 변화나 자기 탐색을 피하려는 태도입니다.","r":[]},"가족구도":{"d":"한 사람이 어린 시절 가족 안에서 차지한 위치와 형제 관계의 구조입니다.","r":[]},"워밍업":{"d":"심리극이나 집단을 시작할 때 긴장을 풀고 분위기와 신뢰를 만드는 준비 단계입니다.","r":["연출자"]},"연출자":{"d":"심리극에서 극을 이끄는 상담자로 주인공이 문제를 표현하도록 돕습니다.","r":["워밍업"]},"기초선":{"d":"개입 전에 측정한 행동 수준으로 효과를 비교하는 기준이 됩니다.","r":["추후평가"]},"추후평가":{"d":"집단이 끝난 뒤 일정 기간이 지나서 효과가 유지되는지 확인하는 평가입니다.","r":["기초선"]},"사전동의서":{"d":"활동 내용과 위험, 권리를 충분히 알린 뒤 참여자가 동의했음을 적은 문서입니다.","r":[]}},"notes":{"갈등을 회피하지 않고 탐색할 수 있는 방법을 찾는다":"갈등을 덮어 두지 않고 다룰 수 있는 길을 찾아 집단이 성장하게 합니다.","감당할 수 있을 만큼의 자기개방을 하도록 안내한다":"너무 깊은 이야기까지 한꺼번에 하지 않고 자신이 감당할 수 있는 만큼만 말하도록 안내합니다.","개인상담의 치료적 관계와 유사한 개념이다":"개인상담에서 상담자와 내담자가 맺는 신뢰 관계와 비슷한 역할을 집단에서 합니다.","격려를 통해 집단원들에게 용기를 북돋아 주고 사회적 관심을 갖게 하고, 생활양식을 수정하도록 한다":"개인심리학은 용기를 북돋워 사회에 관심을 갖게 하고 삶의 방식을 고치게 합니다.","공통의 관심사나 어려움을 경험했던 사람들끼리 집단을 이끌어간다":"같은 문제를 겪은 사람들이 전문가 없이 스스로 모임을 운영합니다.","공통적인 관심사가 있는 집단원들로 구성되어 특정문제와 관심사에 대해 공유한다":"같은 관심사나 어려움을 가진 사람들이 서로의 문제를 나누며 힘을 얻는 집단입니다.","과거의 경험을 분석ㆍ해석하고 무의식적 수준에서 작동하는 심리적 역동에 대해 통찰하도록 한다":"정신분석 집단은 지난 경험과 그 밑에 깔린 무의식의 움직임을 이해하게 합니다.","교육을 목적으로 실시하는 경우라도 반드시 사전동의서를 받아야 한다":"치료가 아닌 교육 목적이어도 사전동의서는 면제되지 않고 반드시 받아야 합니다.","교육자와 촉진자의 역할을 동시에 수행한다":"교육집단에서 상담자는 지식을 전달하면서 집단 과정도 진행하는 두 가지 일을 합니다.","구조화는 집단원의 집단참여에 대한 불안을 어느 정도 줄여준다":"진행 방식을 미리 알려 주면 집단원이 낯선 상황에서 느끼는 불안이 줄어듭니다.","구조화 집단에서 갈등이 발생할 경우 구조화 활동을 잠시 미루고 갈등을 다루는 것이 바람직 하다":"계획한 활동을 고집하기보다 터져 나온 갈등을 먼저 풀어 주는 편이 낫습니다.","구체적인 기법보다는 집단상담자의 촉진적인 태도를 강조한다":"인간중심 집단은 정해진 기술보다 상담자의 따뜻하고 촉진적인 자세를 핵심으로 봅니다.","그러한 행동을 통해 얻고자 하는 바를 탐색한다":"대화를 독차지하는 이유가 불안 때문인지 인정 욕구인지 살펴봅니다.","긍정적인 피드백 이후에 줄 때 더 쉽게 받아들여진다":"칭찬을 먼저 건넨 뒤에 부정적 내용을 전하면 방어가 줄어 수용되기 쉽습니다.","다양한 문화적 배경을 가진 집단원들 간의 상호 이해에 적합하다":"기법보다 태도를 중시하므로 서로 다른 문화의 집단원이 있어도 이해와 존중을 쌓기 좋습니다.","다양한 집단원들과 함께 대인관계 기술을 연습할 수 있다":"여러 성격의 집단원과 어울리며 실제 대인관계에서 쓸 기술을 연습할 수 있습니다.","다음 단계에 진입해서 정체되기도 하고, 일시적으로 이전 단계로 퇴보하는 경우도 있다":"다음 단계로 넘어간 뒤에도 머물러 있거나 불안이 커지면 잠시 앞 단계로 돌아가기도 합니다.","대상에게 맞는 집단의 주제와 목적을 설정하고, 이를 달성하기 위한 목표를 구체화한다":"대상의 필요에 맞는 주제와 목적을 정하고 이를 이루기 위한 구체적 목표를 세웁니다.","마라톤집단에서는 며칠 동안 집중 회기를 통해 심화된 상호작용이 활성화될 수 있다":"며칠간 오래 이어지는 회기에서 집단원들이 깊은 상호작용을 하게 됩니다.","매 회기를 철저히 준비하되 주어진 회기마다 구성과 주제를 조절할 수 있는 융통성이 있어야 한다":"회기마다 준비는 철저히 하되 집단의 상태에 따라 내용을 바꿀 수 있어야 합니다.","면접을 통한 평가는 특정 시점보다 전 과정에 걸쳐 이루어진다":"면접은 한 번에 끝내는 것이 아니라 집단이 진행되는 내내 이어서 합니다.","문제행동을 보이는 집단원의 인격을 폄하하지 않는다":"행동에 대해서는 말하되 사람 자체를 깎아내리지 않아야 합니다.","방관하거나 불필요한 이야기를 길게 하는 식의 저항이 나타난다":"집단 참여를 피하려는 무의식적 방어가 침묵이나 쓸데없는 긴 이야기로 나타납니다.","방어하는 행동을 멈추도록 강요하지 않는다":"방어는 보호 수단이어서 억지로 못 하게 하면 오히려 더 단단히 닫힙니다.","부정적인 피드백보다 더 잘 받아들여진다":"좋은 점을 알려 주는 피드백이 비판보다 더 쉽게 받아들여집니다.","분석ㆍ사정 단계에서는 집단원의 부적절한 생활양식을 파악하고 집단원의 신념, 감정, 동기, 목표를 이해한다":"두 번째 단계로, 집단원의 잘못된 생활양식과 그 바탕의 신념과 동기를 파악합니다.","비밀유지의 한계에 대해 명확하게 알려준다":"비밀이 지켜지지 않는 예외 상황이 있음을 숨기지 않고 알립니다.","비합리적 신념을 변화시킴으로써 부정적인 감정을 완화시킨다":"그릇된 믿음을 합리적 신념으로 바꾸면 부정적인 감정이 누그러집니다.","상담관계형성 단계에서는 상담자와 집단원은 우호적이며 대등한 관계가 형성되어야 한다":"아들러 상담의 첫 단계로, 상담자가 위에서 지시하지 않고 대등하게 협력하는 관계를 맺습니다.","상담자가 집단상담 전후에 심리검사를 실시하여 집단원 행동 변화를 평가할 때 평가의 주체는 상담자, 평가 대상은 집단원이 된다":"상담자가 검사를 해서 집단원의 변화를 보면 평가하는 사람은 상담자이고 평가받는 대상은 집단원입니다.","상담자는 집단원의 학습효과를 극대화하기 위해":"교육집단의 상담자는 가르치는 역할과 참여를 이끄는 역할을 함께 맡습니다.","상담 활동에 대한 사전 동의를 구해야 한다":"청소년 집단상담은 보호자나 법정대리인의 사전 동의를 받는 절차가 따릅니다.","새로운 행동을 시도하고 현실을 검증할 기회를 제공한다":"집단 안에서 안전하게 새 행동을 해 보고 그것이 현실에서 통하는지 확인하게 합니다.","선택할 수 있도록 적절한 정보를 제공해야 한다":"선택에 필요한 정보를 충분히 주어야 집단원이 자유로운 판단으로 참여를 정할 수 있습니다.","수용할 수 없는 자신의 생각, 감정, 행동, 동기를 타인에게 돌리는 것이다":"받아들이기 힘든 자기 마음을 자기 것으로 인정하지 않고 상대에게 있다고 돌립니다.","스스로 책임지고 선택한 방법으로 각자의 심리적 욕구를 충족할 수 있도록 한다":"현실치료는 자신이 선택한 행동으로 기본 욕구를 채우도록 합니다.","시연단계에서는 연출자가 다양한 기법을 활용하여 주인공의 무의식 속 욕망, 갈등 등이 드러나게 한다":"중간 단계로, 연출자가 여러 기법으로 주인공의 숨은 욕망과 갈등이 드러나게 합니다.","심리검사를 통해 수치화된 정보를 수집하고 통계적으로 분석하는 것을 양적 평가라 한다":"검사로 숫자 자료를 모아 통계로 분석하는 평가가 양적 평가입니다.","아동ㆍ청소년과 관련된 법률을 숙지하고 있어야 한다":"미성년자를 상담할 때 지켜야 할 법적 기준을 상담자가 알고 있어야 합니다.","아동과 청소년이 집단에서 얻을 수 있는 이점을 학교 담당자, 교사, 부모에게 명확히 설명해야 한다":"집단이 어떤 도움이 되는지 주변 어른에게 알려 협조를 구해야 합니다.","어린 시절에 격려 받고 학습되어진 친숙한 정서로써 다양한 상황에서 경험된다":"어릴 때 인정받으며 익혀 온 익숙한 감정으로, 여러 상황에서 반복해서 경험됩니다.","여러 사람들이 모여서 자신의 성장과 변화를 도모하는 상담경험이다":"여러 사람이 함께 모여 자기 성장과 변화를 위해 경험을 나누는 상담 형태입니다.","요약해서 말해줄 것을 요청한다":"말이 길어져 흐름을 끊을 때는 핵심만 간추려 달라고 부탁합니다.","워밍업 단계에서는 심리극이 시작되기 전 집단의 목표, 한계 등을 안내한다 · 연출자의 준비, 신뢰감 형성 등의 활동이 포함된다":"심리극의 첫 단계로, 시작 전에 목표와 한계를 안내하고 신뢰를 쌓는 준비를 합니다.","이론적 배경에 따라 구조화의 정도와 종류가 다르다":"상담 접근에 따라 정해 놓고 이끄는 정도와 방식이 달라집니다.","이질집단보다 빨리 자기개방이 이루어지고 유대감이 형성될 수 있다":"비슷한 사람끼리 모이면 마음을 일찍 열고 서로 가까워지는 속도가 빠릅니다.","일부 집단원이 중도에 탈락할 경우 · 집단 크기가 너무 작아질 염려가 있다":"새 사람을 받지 않기 때문에 중도에 빠지는 사람이 생기면 인원이 줄어드는 약점이 있습니다.","일정기간 동안 집중적으로 실시하는 형태이며, 마라톤 집단이 해당된다":"짧은 기간에 몰아서 진행하는 방식으로, 마라톤 집단이 대표적입니다.","자기 파괴적인 행동을 반복할 때 잠시 멈추고 자신을 살펴보도록 한다":"같은 행동을 되풀이하려 할 때 잠시 멈추고 자신의 상태를 돌아보게 합니다.","자신의 요구 또는 감정을 자각하는 것이 두려워 책임을 타인에게 돌리는 현상이다":"두려워서 받아들이지 못하는 자기 마음의 책임을 남에게 넘기는 방어입니다.","자신의 잠재력 개발에 관심 있는 사람들로 구성된다":"정상적인 기능을 하면서 더 나아지고 싶은 사람들이 모입니다.","적극적 경청과 공감적 반응으로 집단행동의 모범을 보인다":"상담자가 먼저 잘 듣고 공감하는 모습을 보이면 집단원이 이를 따라 배웁니다.","적극적으로 경청하고 반응하기와 같은 기본적인 대인관계 기술을 알려준다":"잘 듣고 반응하는 기본 기술을 알려 주어 집단 안에서 서로 소통하게 합니다.","전이 반응을 탐색할 수 있는 기회를 제공한다":"집단원이 과거 인물에게 느끼던 감정을 상담자나 집단원에게 옮기는 반응을 다룰 기회를 줍니다.","종결단계에서는 연출자는 참여자들이 심리극 과정에 참여하면서 느낀 소감을 주인공과 함께 나누도록 돕는다":"마지막 단계로, 참여자들이 경험한 소감을 주인공과 나누게 합니다.","지도자가 다른 지도자에 대항하여 집단원과 한 편을 이루는 단점도 있다":"공동지도자 사이에 갈등이 있으면 한 지도자가 집단원과 한 편이 되어 대립하는 문제가 생깁니다.","지도자의 신체적ㆍ정서적 소진 가능성이 줄어든다":"지도자 둘이 일을 나누므로 한 사람이 지쳐서 소진되는 위험이 줄어듭니다.","지도자 중 한 명은 강한 정서를 표현하는 집단원에 집중하고, 다른 지도자는 나머지 집단원들의 반응에 주목할 수 있다":"한 사람은 감정이 격한 집단원을, 다른 사람은 집단 전체의 분위기를 살필 수 있습니다.","지도자 중 한 명이 역전이가 일어날 때 도움이 된다":"한 지도자가 집단원에게 개인 감정을 투영해도 다른 지도자가 균형을 잡아 줄 수 있습니다.","집단 과업이 달성된 후에도 새로운 갈등이 일어날 수 있다":"한 과제를 마쳐도 집단에 갈등이 다시 생길 수 있어 갈등이 완전히 끝나는 시점은 없습니다.","집단 발달이 어느 정도 이루어지고 · 신뢰관계가 형성되었을 때 하는 것이 효과적이다":"집단의 신뢰가 충분히 쌓인 뒤에 해야 부정적 피드백이 상처로만 남지 않습니다.","집단상담 계획단계에서부터 집단상담 평가에 대한 방향을 설정하여야 한다":"평가는 끝난 뒤에 생각하지 않고 처음 계획할 때부터 방향을 정해야 합니다.","집단상담 계획 시에 집단상담 효과성 평가를 위한 계획을 수립해야 한다":"계획 단계에서 효과를 어떻게 확인할지 미리 계획을 세워야 합니다.","집단상담 실시 이전에 집단상담 수요 평가, 집단원 행동 기초선 평가를 실시할 수 있다":"시작 전에 필요한 정도와 집단원의 현재 행동 수준을 재어 비교 기준을 마련합니다.","집단상담에 관한 이해를 높인다":"참여하기 전에 집단상담이 무엇인지 알려 두면 막연한 두려움이 줄어듭니다.","집단상담에 대한 현실적인 기대 형성을 돕는다":"집단이 만능이 아니라는 점을 알려 과도한 기대나 실망을 막습니다.","집단상담에 대해 집단원이 충분한 설명을 듣고":"충분히 알고 난 뒤 자기 뜻으로 참여를 결정할 수 있어야 동의가 의미를 가집니다.","집단상담의 목표와 한계에 대해 명확히 알려야 한다":"집단원이 무엇을 얻을 수 있고 무엇은 기대하기 어려운지 처음에 분명히 알려야 합니다.","집단상담이 끝나고 1～2개월 후 추후평가를 실시하여 집단상담의 효과를 평가한다":"집단이 끝난 뒤 일정 기간이 지나서도 효과가 유지되는지 추후평가로 확인합니다.","집단상담이 적절하지 않다고 판단되는 경우 개인상담을 권유한다":"집단이 도움이 되지 않거나 해가 될 수 있다고 판단되면 개인상담으로 연결합니다.","집단상담자는 열정적이고 긍정적인 태도를 갖는다":"집단상담자는 열의와 긍정적인 태도로 집단에 에너지를 줍니다.","집단상담자는 진실해야 하지만 무분별하게 개방적이어서는 안 된다":"상담자는 솔직해야 하지만 아무 감정이나 모두 드러내서는 안 되고 집단에 도움이 될 때만 개방합니다.","집단상담자에게 집중되는 것을 피하고 집단원간의 상호작용을 촉진시킨다":"상담자와 집단원의 일대일 대화로 흐르지 않도록 집단원끼리 대화를 이어 주게 합니다.","집단상담자와 집단원 모두의 권리와 책임에 대해 알려야 한다":"양쪽이 가지는 권리와 지켜야 할 책임을 함께 설명하여 사전동의의 내용을 채웁니다.","집단상담자와 집단원의 책임과 역할을 명확히 한다":"누가 무엇을 맡는지 분명히 해 두어야 집단원이 자신의 몫을 압니다.","집단상담자의 진실성, 수용, 공감은 집단원의 성장을 촉진한다":"로저스는 상담자의 태도가 만드는 안전한 분위기가 집단원을 성장시킨다고 보았습니다.","집단상황을 집단원이 실제로 살고 기능하는 세계의 축소판으로 본다":"집단 안에서 나타나는 행동이 집단원의 현실 삶의 모습을 줄여 놓은 것이라고 봅니다.","집단에 대한 구조화를 실시하여 집단에 대해 안내한다":"집단의 목적과 규칙, 진행 방식을 설명해 집단원이 어떻게 해야 할지 알게 합니다.","집단에서의 행동과 관련된 ‘지금-여기’ 피드백이 · 모호한 피드백보다 더 도움이 된다":"지금 집단에서 한 행동에 대한 구체적 반응이 막연한 평가보다 도움이 됩니다.","집단에서 이루어지는 작업은 쉽지 않음을 알리고 적극적인 참여를 독려한다":"변화를 위한 작업은 힘들 수 있다는 점을 미리 알려 중도에 포기하지 않게 격려합니다.","집단에 참여하기 어려운 집단원을 선별할 수 있다":"집단이 맞지 않는 사람을 미리 가려내 개인상담 등 다른 서비스로 연결합니다.","집단원, 집단상담자 및 집단상담 과정을 평가한다":"평가는 참여한 사람과 이끈 사람, 그리고 집단이 진행된 과정까지 대상으로 합니다.","집단원과의 협의 하에 수행할 과제를 주고 확인한다":"집단원과 합의해 정한 과제를 내고 다음 회기에 수행했는지 확인하는 방식입니다.","집단원과 집단의 진행과정에 대해 솔직하게 이야기를 나눈다":"집단이 어떻게 진행되는지에 관해 숨기지 않고 터놓고 이야기합니다.","집단원과 함께 집단의 기본규칙에 관하여 논의한다":"규칙을 일방적으로 정하지 않고 함께 논의해 정하면 더 잘 지키게 됩니다.","집단원들에게 당면한 과제를 해결할 필요가 있을 때 운영되는 집단이다":"눈앞에 닥친 과제를 풀어야 할 때 만들어지는 집단입니다.","집단원들은 기본적으로 자유로운 존재이기에 자유에 동반되는 책임을 받아들여야 한다":"사람은 자유로운 존재여서 선택에 대한 책임도 스스로 받아들여야 합니다.","집단원들의 관심을 높일 수 있도록 놀이나 매체를 활용할 수 있다":"놀이나 영상 같은 매체로 흥미를 높이면 청소년의 참여가 늘어납니다.","집단원들의 염려와 질문을 개방적으로 다룬다":"초기에 나오는 걱정과 궁금증을 피하지 않고 열린 태도로 다룹니다.","집단원들이 구체적인 개인 목표를 설정하도록 돕는다":"막연한 바람이 아니라 실제로 이룰 수 있는 개인 목표를 세우게 돕습니다.","집단원들이 실존적 문제를 나눔으로써 자신을 발견하도록 돕는다":"죽음이나 고독 같은 삶의 근본 문제를 함께 나누며 자기를 알아 갑니다.","집단원에 대한 역전이가 일어날 수 있다":"상담자가 집단원에게 자기의 과거 감정을 투영하는 일이 생길 수 있습니다.","집단원으로서의 책임과 권리를 인식할 수 있도록 한다":"집단원이 자신이 가진 권리와 지켜야 할 의무를 알도록 안내합니다.","집단원은 평가 대상이면서 평가자가 되기도 한다":"집단원은 평가받는 입장이면서 집단에 대한 의견을 주는 평가자이기도 합니다.","집단원의 개인적인 변화를 촉진하기 위해":"상담 시간 밖에서도 변화가 이어지도록 합의한 과제를 주고 수행했는지 확인합니다.","집단원의 내면세계를 정서적으로 공유하고 집단으로부터 수용되는 것이다":"자신의 속마음을 집단에서 나누고 받아들여진다고 느끼는 것이 응집력의 본질입니다.","집단원의 변동이 가능하므로 · 폐쇄집단보다 다양한 사람들과 상호작용할 수 있다":"중간에 사람이 들어오고 나갈 수 있어 다양한 사람과 만날 기회가 많습니다.","집단원의 비합리적 신념을 합리적 신념으로 바꾸는 것을 목표로 한다":"그릇된 믿음을 합리적인 믿음으로 대체하는 것이 중심 목표입니다.","집단원의 사회적 상황과 사회적 태도를 파악한다":"집단원이 놓인 사회적 환경과 타인에 대한 태도를 함께 파악합니다.","집단원의 생활양식을 파악하기 위해 가족구도를 탐색한다":"아들러 접근에서는 어린 시절의 가족 내 위치와 관계를 통해 삶의 방식을 알아냅니다.","집단원의 성숙도, 집단의 유형 등에 따라 집단의 크기를 정한다":"집단원의 나이와 성숙도, 집단 종류에 따라 알맞은 인원수가 달라집니다.","집단원의 소감이나 경험보고서는 집단과정에 대한 중요한 평가 자료로 활용된다":"집단원이 쓴 소감이나 경험 보고는 집단 과정을 평가하는 중요한 근거가 됩니다.","집단원의 인지적 변화를 위해 다양한 인지적, 정서적 기법을 활용한다":"생각을 바꾸는 방법과 감정을 다루는 방법을 함께 써서 변화를 이끕니다.","집단원의 집단에 대한 기대를 탐색한다":"집단원이 집단에서 얻으려는 것이 무엇인지 물어 비현실적 기대를 조정합니다.","집단원의 집단참여에 대한 불안감 해소를 돕는다":"낯선 곳에서 느끼는 불안을 말로 풀게 해 참여를 쉽게 합니다.","집단원의 통찰을 나누는 것은 집단의 발전을 촉진한다":"깨달음을 서로 나누면 다른 집단원의 이해도 깊어져 집단이 발전합니다.","집단원이 자기 삶의 전문가라고 믿고 · ‘알지 못함’(not-knowing)의 자세를 취한다":"집단원이 자기 삶을 가장 잘 안다고 보아 모르는 사람의 자세로 질문합니다.","집단원이 자기 삶의 전문가이므로 · 상담자는 알지 못함의 자세를 취해야 한다":"답을 아는 사람은 상담자가 아니라 집단원이므로 상담자는 가르치려 하지 않습니다.","집단원이 자신과 환경을 이해하고 자신을 수용하며 접촉할 수 있는 힘을 증진시킨다":"게슈탈트 집단은 지금의 자신과 주변을 알아차리고 받아들여 환경과 접촉하는 힘을 키웁니다.","집단원이 현재 무엇을 하고 있는지에 초점을 맞추도록 한다":"과거나 감정보다 지금 하고 있는 행동에 주의를 모으게 합니다.","집단은 역동적, 지속적으로 변화하는 특징을 지니고 있다":"집단은 고정된 것이 아니라 시간이 가면서 계속 달라지는 살아 있는 과정입니다.","집단을 완료하지 못할 경우 어떤 결과가 초래되는지 안내한다":"집단을 끝까지 마치지 못하면 어떤 불이익이나 영향이 있는지 미리 알려 줍니다.","집단응집력은 그 자체가 강력한 치료적인 힘이다":"응집력이 높으면 그것만으로도 집단원에게 도움이 되는 치료적 효과가 생깁니다.","집단응집력이 높을수록 출석, 참여, 상호지지의 비율이 더 높아진다":"집단에 대한 끌림이 클수록 빠지지 않고 참여하며 서로 지지해 주는 정도가 커집니다.","집단의 목표는 자신이 자기 삶의 주인이어야 한다는 자유를 인식하고 수용하는 것이다":"실존주의 집단은 자기 삶을 스스로 책임지는 자유를 깨닫는 것을 목표로 합니다.","집단의 발달단계는 실제로 중첩되기도 한다":"집단은 단계가 칼로 자르듯 나뉘지 않고 앞뒤 단계의 특징이 겹쳐 나타나기도 합니다.","집단의 종류나 목적에 따라 모임의 시간과 주기를 결정한다":"모임 길이와 횟수는 집단의 종류와 목적에 따라 정합니다.","집단 전체의 목표와 집단원 개인의 목표로 나눌 수 있다":"목표는 집단이 함께 이룰 것과 집단원 각자가 이룰 것, 두 갈래로 세웁니다.","집단 종결 전에 집단원에게 어느 정도의 기간을 두고 종결 시점을 상기시켜 준다":"종결이 갑작스럽지 않도록 미리 여러 번 끝이 다가옴을 알려 줍니다.","집단 진행에 방해가 되지 않는 조용한 공간으로 선택한다":"소음이나 드나듦이 없는 조용한 곳이어야 집단원이 안심하고 이야기합니다.","집단참여에 대한 감정을 표현할 수 있도록 돕는다":"억지로 온 집단원에게는 참여가 싫은 마음을 먼저 인정하고 표현하게 합니다.","집단 참여에 대한 압력을 받아 심리적 부담을 느낄 수 있다":"남들 앞에서 참여해야 한다는 압박이 있어서 집단원이 마음의 부담을 느낄 수 있습니다.","집단참여 촉진을 위한 정보를 제공한다":"집단에 참여하도록 용기를 주는 정보를 사전에 전달합니다.","집단회기 전후에 공동지도자와 집단에 대한 계획과 소감, 서로의 협력에 대해 논의한다":"공동으로 이끄는 사람끼리 회기 전에는 계획을, 후에는 소감과 협력 방식을 조율합니다.","참만남 집단, 자기성장 집단, 감수성 훈련집단이 해당된다":"치료가 아니라 개인의 성장을 돕는 집단들이 성장집단에 속합니다.","청소년 상담기관에서 집단상담을 실시할 경우 상담기관이 평가주체가 될 수 있다":"청소년 상담기관이 운영하는 집단은 기관이 평가를 맡을 수 있습니다.","청소년인 경우, 보호자 또는 법정대리인의":"미성년자는 스스로 동의할 능력이 제한되어 보호자나 법정대리인의 허락도 받습니다.","특정과업을 완수하기 위한 목적으로 구성된다":"상담 목적이 아니라 맡은 일을 끝내는 것이 구성 목적입니다.","평가방법은 주로 면접, 심리검사, 관찰 등으로 이루어진다":"면접과 심리검사와 관찰이 평가에 쓰이는 대표적인 방법입니다.","폐쇄집단에서 집단원이 집단을 떠나고 싶어하면 이를 존중해 준다":"떠나고 싶다는 뜻을 막지 않고 존중하되 그 이유를 이야기할 기회를 줍니다.","학교장의 승인을 받아 실시해야 한다":"학교에서 집단을 운영하려면 학교장의 허락을 먼저 받아야 합니다.","학습, 진로만이 아니라 문제행동 및 예방을 주제로 한다":"청소년 집단상담의 주제는 공부와 진로뿐 아니라 문제 행동과 그 예방까지 포함합니다.","합리적-정서적 상상하기, 유머 사용하기 등의 정서적 기법을 활용한다":"상상 속에서 감정을 바꿔 보는 연습이나 웃음을 활용해 비합리적 신념을 약화시킵니다.","해석ㆍ통찰 단계에서는 상담자는 집단원의 진술에 대한 해석을 통해 집단원의 자각과 통찰을 돕는다":"세 번째 단계로, 상담자의 해석을 통해 집단원이 자신을 깨닫도록 돕습니다.","현실적으로 완벽한 비밀보장이 어렵다는 것을 사전에 알려 준다":"집단에서는 다른 집단원이 비밀을 지킨다고 장담할 수 없어 그 한계를 처음에 알려야 합니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
